REPLACE INTO `media` VALUES (1,'2026/10/2aobor5evufktut5yfbobsfbyisynny8p8zsr8l21-7a2368','2aobor5evufktut5yfbobsfbyisynny8p8zsr8l21.jpg','image/webp',1440,960,149718,'',NULL,50,56,1,'2026-10-13 22:13:35','2026-10-13 22:13:35'),(2,'2026/10/2aobor5evufmujpttsu0sdq2zft0r4qj2wpbhc2c2-645a2f','2aobor5evufmujpttsu0sdq2zft0r4qj2wpbhc2c2.jpg','image/webp',1440,960,113766,'',NULL,50,41,1,'2026-10-13 22:13:37','2026-10-13 22:13:37'),(3,'2026/10/2aobor5evuwgbpigsfaezmu1nfyaxk3gozy7rrzq3-aad272','2aobor5evuwgbpigsfaezmu1nfyaxk3gozy7rrzq3.jpg','image/webp',1440,960,153058,'',NULL,50,44,1,'2026-10-13 22:13:39','2026-10-13 22:13:39'),(4,'2026/10/2aobor5evvogdriu1ftcphalicn2jbprizyigwag4-ff2be1','2aobor5evvogdriu1ftcphalicn2jbprizyigwag4.jpg','image/webp',1440,1082,79694,'',NULL,50,72,1,'2026-10-13 22:13:41','2026-10-13 22:13:41'),(5,'2026/10/2aobor5evw8tqadifc1aysdsulfim4q8lvscssvw5-d598c2','2aobor5evw8tqadifc1aysdsulfim4q8lvscssvw5.jpg','image/webp',1440,960,181246,'',NULL,50,31,1,'2026-10-13 22:13:43','2026-10-13 22:13:43'),(6,'2026/10/2aobor5evwrqnr0omubrhfwcjrvca5l2s7ydft4a6-29aec5','2aobor5evwrqnr0omubrhfwcjrvca5l2s7ydft4a6.jpg','image/webp',1440,960,184078,'',NULL,50,60,1,'2026-10-13 22:13:44','2026-10-13 22:13:44'),(7,'2026/10/2aobor5evxjuzmsmaqvetvecvklcoeao1qwg84ao7-2ba0ce','2aobor5evxjuzmsmaqvetvecvklcoeao1qwg84ao7.jpg','image/webp',1440,960,151262,'',NULL,50,35,1,'2026-10-13 22:13:47','2026-10-13 22:13:47'),(8,'2026/10/2aobor5evykmmffp4mlnvammpa8m4vgw7cwd4jms9-2908cf','2aobor5evykmmffp4mlnvammpa8m4vgw7cwd4jms9.jpg','image/webp',1440,1073,78348,'Cảnh phim ĐỢI: người phụ nữ mặc váy ren trắng ngồi xe lăn điện ở vạch sang đường, nhìn về phía trước',NULL,52,59,1,'2026-10-13 22:13:48','2026-10-13 22:27:30'),(9,'2026/10/2aobor5evyphipg5ezn6ushayo6aaonoieebpx6e8-55e675','2aobor5evyphipg5ezn6ushayo6aaonoieebpx6e8.jpg','image/webp',1440,1080,63582,'',NULL,50,72,1,'2026-10-13 22:13:50','2026-10-13 22:13:50'),(10,'2026/10/2aobor5evz6w1qtpvozdakdbx7nmx3ysk1zssm4e10-95b9ec','2aobor5