REPLACE INTO `posts` VALUES (1,'khong-de-nguoi-khac-quyet-dinh-gioi-han-cua-ban-than','Không để người khác quyết định giới hạn của bản thân','Một câu chê thẳng mặt, hai ngày ra trường quay với cánh tay cháy nắng, và vai diễn từng bị “dự báo” làm bể phim.','Hôm qua ngồi xem series *Agency*, nghe câu thoại của nhân vật chính, mình phải note lại liền: **“Không để người khác quyết định giới hạn của bản thân.”**\n\nNhớ lại hồi mình chuẩn bị làm phim ngắn ĐỢI, hí hửng khoe với ông bạn sẽ tự đóng vai chính. Ông bạn bốp chát luôn vào mặt mình:\n\n> Bà mà đóng vai chính, phim của bà bể là cái chắc.\n\nCũng phải thừa nhận khả năng này có thể xảy ra vì mình chưa từng làm diễn viên, cũng chưa học qua lớp diễn xuất nào. Viết kịch bản chưa ổn thì còn ngồi sửa được chứ ra trường quay mà diễn đơ, cả đoàn đứng chờ thì áp lực lắm.\n\n## Nhận vai, rồi tập như thật\n\nNhưng vai An mình vẫn nhận, thứ nhất là vì kinh phí làm phim ít, thứ hai là mình muốn trải nghiệm một lần ở vị trí mới. Có điều từ hôm ấy mình đọc kịch bản kỹ hơn, tự luyện tập diễn xuất nhiều hơn. Cảnh nào có cảm xúc khó, mình tập diễn trước, còn nhờ chị sang Việt Trì quay để xem mình diễn thế nào rồi sửa. Chưa biết lên phim thế nào chứ ở nhà đã có một cameraman kiêm khán giả bất đắc dĩ để mình luyện rồi hẹ hẹ.\n\n## Người lạ ở Sài Gòn và một lời khen\n\nHôm trước, một bạn trong Sài Gòn nhắn rằng bạn đã xem phim ĐỢI tại đêm chung kết Inspiring Vietnam 2026 và khen nét diễn của mình. Hóa ra cái vai từng được dự báo là nguyên nhân khiến phim thất bại lại có người thích.\n\nĐúng là giới hạn của bản thân đâu thể nằm ở mồm người khác, giới hạn của mình nằm ở việc mình có dám dấn thân.',NULL,1,NULL,'published','2026-09-20 09:00:00',NULL,NULL,'vi','facebook','bai_viet/facebook_thanhthanh/bai_viet_thang_9.txt#1',0,NULL,'2026-10-13 20:02:51','2026-09-20 09:00:00'),(2,'dung-giua-cho-rau-rao-ban-sach-account','Đứng giữa chợ rau rao bán sách Account: bài học về khán giả mục tiêu','Trước khi viết, câu đầu tiên phải trả lời: mình kể câu chuyện này cho ai xem?','Khum ngờ bên Threads cũng bán được đồ mọi người ạ.\n\nMình có khóa học đem pass, dành cho những bạn sinh viên mới ra trường muốn tìm hiểu ngành Account. Vậy mà ban đầu mình lại hí hửng mang khóa học vào pass các nhóm mẹ bỉm sữa. Và kết quả KHÔNG một ai hỏi han, nhòm ngó.\n\n## Kể cho ai xem?\n\nChuyện này khiến mình liên tưởng đến một nguyên tắc cốt lõi trong viết kịch bản: tính phù hợp với khán giả mục tiêu. Trước khi viết, điều đầu tiên cần xác định là sẽ kể câu chuyện này cho ai xem?\n\nCùng một chủ đề về tình yêu nhưng viết cho khán giả tuổi teen sẽ khác với người đã lập gia đình.\n\n> Không xác định đúng người cần thì sản phẩm có tốt đến đâu, mình cũng chỉ đang đứng giữa chợ bán rau mà rêu rao bán sách học Account.',NULL,2,NULL,'published','2026-09-15 09:00:00',NULL,NULL,'vi','facebook','bai_viet/facebook_thanhthanh/bai_viet_thang_9.txt#2',0,NULL,'2026-10-13 20:02:51','2026-09-15 09:00:00'),(3,'giay-phep-phan-loai-phim','Giấy phép phân loại phim: chiếc vé thông hành ai làm phim cũng cần','Nộp online, khoảng 10 ngày, lệ phí 1,6 triệu cho phim dưới 60 phút. Kinh nghiệm thật từ ĐỢI.','Hành trình ĐỢI được công chiếu tại Chung kết Inspiring Vietnam 2026 không thể thiếu chiếc **giấy phép phân loại phim**.\n\nMuốn có chiếc giấy phép này, nhà làm phim phải nộp hồ sơ trên Cổng Dịch vụ công Quốc gia. Cơ quan giải quyết là Bộ Văn hóa, Thể thao và Du lịch (Cục Điện ảnh).\n\n## Mất bao lâu, tốn bao nhiêu?\n\n- Khoảng 7 ngày sau khi nộp hồ sơ có kết quả cấp phép.\n- Khoảng 3 ngày sau nữa nhận giấy phép bản cứng.\n- Phim dưới 60 phút, phi thương mại: lệ phí 1 triệu 6.\n\nVới một người khó đi lại như mình, việc gần như mọi thứ đều làm được online thực sự là phần dễ thở nhất trong quá trình làm phim.',NULL,2,NULL,'published','2026-09-10 09:00:00',NULL,NULL,'vi','facebook','bai_viet/facebook_thanhthanh/bai_viet_thang_9.txt#5',0,NULL,'2026-10-13 20:02:51','2026-09-10 09:00:00'),(4,'bai-nhap-khong-duoc-hien','Bài nháp – không được hiện ra ngoài',NULL,'Nội dung nháp.',NULL,1,NULL,'draft',NULL,NULL,NULL,'vi','manual',NULL,0,NULL,'2026-10-13 20:02:51','2026-10-13 20:02:51'),(5,'lan-dau-chia-se-tai-tru-so-lien-hop-quoc-the-gioi-dang-song-hon','Lần đầu chia sẻ tại trụ sở Liên Hợp Quốc: Thế giới đáng sống hơn','Một cột mốc nhỏ trong hành trình chui ra khỏi vỏ ốc an toàn 10 năm: Đứng trước rất nhiều người tại trụ sở Liên Hợp Quốc và chia sẻ về thế giới đáng sống hơn.','Lần đầu tiên mình và mẹ có một chuyến đi đặc biệt đến trụ sở Liên Hợp Quốc tại Việt Nam.\n\nVới mình, đây lại là một cột mốc nhỏ nhưng mang ý nghĩa lớn trong hành trình chui ra khỏi chiếc vỏ ốc an toàn mà mình đã ru rú suốt 10 năm chỉ quanh quẩn trong phòng.\n\n![Thanh Thanh chia sẻ về hành trình vượt qua giới hạn](/uploads/2026/10/2aobor5evxjuzmsmaqvetvecvklcoeao1qwg84ao7-2ba0ce-960.webp)\n*Cột mốc chui ra khỏi vỏ ốc an toàn 10 năm để đứng trước mọi người và cất lên tiếng nói.*\n\n## Thử thách 20 phút và câu hỏi lớn\n\nThử thách lần này mình tự đặt ra cho bản thân là đứng trước rất nhiều chuyên gia, bạn trẻ và trình bày một bài chia sẻ 20 phút về câu hỏi: **Làm thế nào để xây dựng một thế giới đáng sống hơn?**\n\nNghe chủ đề thì có vẻ to tát, nhưng thực sự một tuần trước khi sự kiện diễn ra, mình vẫn run rẩy đến mất ngủ. Mình tự lên dàn ý, rồi hẹn tập duyệt cùng bạn Minh Tâm cực kỳ nhiệt huyết của Viện iSEE. \n\nLần đầu đọc thử, mình nói một lèo chưa đầy 15 phút đã hết veo nội dung, vừa nhanh vừa cứng nhắc. Hai đứa lại ngồi xuống góp ý, gọt giũa từng câu từng chữ để bài nói mạch lạc hơn, có cảm xúc hơn – giống như một câu chuyện từ tận đáy lòng mình đang kể cho bạn bè nghe chứ không phải một bài văn mẫu sách giáo khoa phải thuộc làu.\n\n## Mẹo tâm lý vượt qua nỗi sợ nói trước đám đông\n\nĐến ba ngày trước sự kiện, ngày nào mình cũng lôi bài chia sẻ ra tu luyện. Mình còn lên YouTube học cách để bớt run khi nói trước đám đông và tình cờ học được một mẹo khá hay: **Hãy coi tất cả những người ngồi trước mặt như những người bạn thân thiết, và mình chỉ đang bước vào, ngồi xuống và chém gió cùng họ một câu chuyện mà mình vô cùng hứng thú.**\n\nMình thử làm theo, liên tục tự nhủ điều đó trong đầu và thấy hiệu quả bất ngờ. Đến lúc thực sự ngồi trước mọi người và bắt đầu cất giọng, mình cảm thấy bình tĩnh hơn tưởng tượng rất nhiều. Thậm chí mình còn đủ tỉnh táo để pha trò vài câu khiến cả khán phòng bật cười nhẹ nhõm.\n\n![Thanh Thanh phát biểu trong không khí ấm áp](/uploads/2026/10/2aobor5evw8tqadifc1aysdsulfim4q8lvscssvw5-d598c2-960.webp)\n*Chia sẻ chân thành luôn có sức lan tỏa mạnh mẽ hơn mọi lời nói hoa mỹ.*\n\n## Được ở trong một căn phòng tràn ngập hy vọng\n\nĐiều đáng giá nhất trong buổi chia sẻ hôm ấy không phải là tràng pháo tay, mà là mình được ngồi cùng rất nhiều bạn trẻ tài năng. Mình được lắng nghe những góc nhìn đa dạng về việc lên tiếng, về niềm tin, về những hành động nhỏ bé mà thiết thực mỗi người đang lựa chọn mỗi ngày để khiến thế giới quanh mình trở nên ấm áp và bình đẳng hơn.\n\nMình thực sự mê cảm giác được ở trong một căn phòng có nhiều người giỏi giang và giàu lòng trắc ẩn như thế. Mỗi người mang theo những kiến thức, trải nghiệm và những cách tiếp cận khác nhau để cùng chung tay kiến tạo một xã hội hòa nhập.\n\nVà cho tới giờ, chuyến đi lần này vẫn là một bước chân ý nghĩa trong hành trình dài: **Xây dựng bản thân trở thành một phiên bản tốt hơn, kiên cường hơn, trước khi mình mong muốn đóng góp xây dựng một thế giới đáng sống hơn.**',7,3,1,'published','2026-09-20 09:30:00','Lần đầu chia sẻ tại trụ sở Liên Hợp Quốc tại Việt Nam','Hành trình bước ra khỏi vỏ ốc 10 năm của biên kịch Thanh Thanh và bài diễn thuyết 20 phút về xây dựng một thế giới đáng sống hơn tại Liên Hợp Quốc.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:33','2026-10-14 06:03:33'),(6,'ekip-dac-biet-cua-doi-nguoi-chuyen-che-nguoi-chuyen-cho','Đội ngũ hậu trường đặc biệt của ĐỢI: Người chuyên chê, người chuyên chở và biên kịch chuyên lì','ĐỢI có một ekip rất đặc biệt: người chuyên chê, người chuyên chăm, người chuyên chở… còn biên kịch làm phim như mình thì chuyên lì.','Đội ngũ làm phim của ĐỢI có mặt tại Lễ Chung Kết Inspiring Vietnam 2026 tại Trung tâm Khởi nghiệp Sáng tạo SIHUB!\n\nTuy không trực tiếp xông pha cầm máy quay, dựng phim hay diễn xuất, nhưng đây chính là đội ngũ hậu trường hùng mạnh nhất đã “chống lưng” cho ĐỢI suốt chặng đường dài vừa qua.\n\n![Đội ngũ hậu trường đặc biệt của phim ngắn ĐỢI tại SIHUB](/uploads/2026/10/2aobor5evufktut5yfbobsfbyisynny8p8zsr8l21-7a2368-960.webp)\n*Gia đình và bạn bè – điểm tựa vững chắc nhất của biên kịch Thanh Thanh.*\n\n## Giám đốc Sở Chê Bai và Ban Hậu Cần đặc biệt\n\nBên trái trong bức hình là ông bạn Hòa – người mình hay gọi vui là “Giám đốc Sở Chê Bai”. Hòa là người đã chê mình từ khâu ý tưởng kịch bản sơ khai cho đến tận lúc mình quyết định ôm luôn vai chính bộ phim. Chê không thiếu một câu, góp ý thẳng thừng thì còn nhiều hơn chê. \n\nNhưng cũng nhờ những lời nhận xét không khoan nhượng ấy mà mình hiểu rõ hơn về ý định câu chuyện, mục tiêu thông điệp và càng quyết tâm làm bộ phim bằng được.\n\nCòn Anh trai và Mẹ chính là Ban Hậu Cần kiêm Bộ phận Vận Chuyển – Cổ Vũ – Chăm Sóc – Hỗ Trợ toàn diện, đồng hành cùng mình từ những ngày đầu tiên chuẩn bị bấm máy cho đến tận đêm chung kết hôm nay. Từng chuyến xe, từng bữa ăn, từng lần nâng bánh xe lăn qua bậc cửa đều có bàn tay của gia đình chở che.\n\n## Khi biên kịch chuyên lì gặp những người thương yêu\n\nNói chung, ĐỢI có một ekip vô cùng đặc biệt:\n\n- Người chuyên chê để kịch bản bớt ngây ngô.\n- Người chuyên chăm để biên kịch không kiệt sức.\n- Người chuyên chở để chiếc xe lăn đến được trường quay.\n- Còn biên kịch làm phim như mình thì... chuyên lì!\n\nToàn những vị trí cốt cán cả về tinh thần lẫn thể chất. Không có sự đồng hành bền bỉ của những người thân thương này, chắc chắn đứa con tinh thần mang tên ĐỢI cũng khó lòng bước ra ánh sáng và đi xa được đến ngày hôm nay.',1,1,1,'published','2026-09-28 10:00:00','Đội ngũ hậu trường đặc biệt của phim ngắn ĐỢI','Đội ngũ hậu trường đặc biệt đã chống lưng cho ĐỢI: Mẹ và anh trai hậu cần, bạn thân chuyên chê và biên kịch chuyên lì.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(7,'buoi-chieu-dau-tien-va-ky-thuat-framing-within-a-frame','Buổi chiếu đầu tiên của ĐỢI tại SIHUB và kỹ thuật Framing within a frame','Khung trong khung (Framing within a frame) – kỹ thuật điện ảnh lột tả hoàn hảo cảm giác bị giam cầm trong sự chờ đợi của nhân vật An.','Buổi chiếu đầu tiên của phim ngắn ĐỢI diễn ra trong không khí xúc động tại Buổi Chiếu phim và Chung kết Inspiring Vietnam 2026 ở SIHUB.\n\nThật may mắn khi có đứa em cùng làm phim đã xin nghỉ hẳn nửa ngày làm việc, chạy xe máy từ Quận 7 sang ngồi xem cùng mình, và bảo thích nhất khung hình này trong phim.\n\n![Màn hình LED giới thiệu phim ĐỢI tại SIHUB](/uploads/2026/10/2aobor5evufmujpttsu0sdq2zft0r4qj2wpbhc2c2-645a2f-960.webp)\n*Phim ngắn ĐỢI trên màn hình lớn tại Lễ Chung Kết Inspiring Vietnam 2026.*\n\n## Đặt nhân vật vào chiếc lồng tâm lý\n\nCá nhân mình khi viết kịch bản đến phân đoạn này cũng đã trăn trở mường tượng làm sao để đặt nhân vật An vào một không gian bức bối và ngột ngạt nhất có thể. Dù không rành về các kỹ thuật set-up ánh sáng phức tạp, nhưng mình chắc chắn một điều: đến đoạn này, An phải bị \"nhốt lại\".\n\nAn bị giam cầm trong cái lồng tâm lý mang tên ĐỢI người khác mà chưa thể thoát ra, đồng thời cũng bị giam trong chính cái quyết định lựa chọn thụ động của mình dẫn đến tình cảnh cô đơn này. Để rồi sau đó, qua những va chạm và trải nghiệm, nhân vật mới tìm thấy động lực bứt phá để giải phóng chính mình.\n\n## Sức mạnh của kỹ thuật \"Khung trong khung\" (Framing within a frame)\n\nTrước khi bấm máy, mình từng tình cờ đọc tài liệu về kỹ thuật **Khung trong khung (Framing within a frame)** trong ngôn ngữ điện ảnh, và mình ấp ủ mong muốn đưa nó vào ĐỢI. \n\nĐó là thủ pháp đặt nhân vật vào bên trong một khung hình phụ (khung cửa sổ, ô cửa kính, vách ngăn kiến trúc...) nằm lồng bên trong khung hình máy quay. Kỹ thuật này tạo cảm giác bị chia cắt, cô lập và tù túng về mặt thị giác.\n\n![An lọt thỏm trong khung cửa sổ gỗ](/uploads/2026/10/2aobor5ew1f0wwg0jcekqavsan9vbq7trjp3h5tk15-08c1a2-960.webp)\n*Kỹ thuật Framing within a frame tạo nên sự cô đơn, tù túng và bất lực sâu sắc.*\n\nVà khoảnh khắc An ngồi lọt thỏm, bơ vơ và bất lực nhất trong chính những hy vọng và nỗi buồn của riêng mình, khung cửa gỗ đã trở thành một \"nhà tù vô hình\". Kỹ thuật framing within a frame đã lột tả hoàn hảo chiều sâu tâm trạng của nhân vật mà không cần đến bất kỳ lời thoại giải thích nào.',14,1,1,'published','2026-09-29 14:00:00','Kỹ thuật Framing within a frame trong phim ngắn ĐỢI','Cách sử dụng kỹ thuật \"Khung trong khung\" để khắc họa cảm giác bị giam cầm trong tâm lý chờ đợi của nhân vật An trong phim ngắn ĐỢI.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(8,'hanh-trinh-dua-phim-ngan-doi-den-chung-ket-inspiring-asia-2026','Hành trình đưa ĐỢI vào Bán kết rồi Chung kết Inspiring Asia 2026 tại Manila','Phim ngắn ĐỢI dài 6 phút chính thức trở thành 1 trong 2 bộ phim đại diện Việt Nam bước vào Chung kết Inspiring Asia 2026 tại Manila.','Phim ngắn ĐỢI dài 6 phút – tác phẩm phim ngắn đầu tay của mình – đã tiếp tục bước vào vòng trong của cuộc thi điện ảnh khu vực Inspiring Asia 2026!\n\nTác phẩm đã đi xa ngoài mọi sự kỳ vọng ban đầu của mình khi quyết định đem những chất liệu đời sống chân thực của người khuyết tật ngồi xe lăn vào màn ảnh lớn.\n\n![Đạo diễn Trịnh Đình Lê Minh trao cúp vinh danh cho Thanh Thanh](/uploads/2026/10/2aobor5evuwgbpigsfaezmu1nfyaxk3gozy7rrzq3-aad272-960.webp)\n*Khoảnh khắc xúc động khi ĐỢI được vinh danh tại Chung kết Inspiring Vietnam 2026.*\n\n## Từ ý tưởng trên giấy đến đấu trường khu vực\n\nLúc tìm ý tưởng phim, mình chỉ mong kịch bản có một góc nhìn lạ một chút, lấy cảm hứng từ những phim ngắn độc lập ấn tượng như *Stutterer* hay *This is John (2003)*. Mà khi ấy, kinh nghiệm viết kịch bản phim ngắn của mình còn rất non nớt, từng bị đạo diễn chỉnh sửa đến nát bét kịch bản, nhiều đêm khóc rấm rứt vì cảm thấy bản thân yếu kém.\n\nNhưng sau khi kịch bản pitching thành công trước đạo diễn Trịnh Đình Lê Minh và chị Phạm Thị Hảo, nhận được tài trợ sản xuất từ ban tổ chức, hành trình thực sự mới bắt đầu. Mình lao vào tìm kiếm ekip làm phim, tập luyện diễn xuất, vượt qua 2 ngày quay nắng gắt bỏng rát trên đường phố Sài Gòn.\n\n![Nhân vật An qua đường giữa dòng xe cộ](/uploads/2026/10/2aobor5evykmmffp4mlnvammpa8m4vgw7cwd4jms9-2908cf-960.webp)\n*Mỗi thước phim là sự dấn thân và nỗ lực không ngừng nghỉ của cả ekip.*\n\n## Vươn tới Chung kết Inspiring Asia 2026 tại Manila\n\nĐầu tiên, ĐỢI vinh dự là 1 trong 4 đại diện Việt Nam lọt vào Bán kết Inspiring Asia. Và mới đây, tin vui lớn nhất đã đến: ĐỢI là 1 trong 2 bộ phim của Việt Nam chính thức bước vào Vòng Chung Kết của **Inspiring Asia 2026** diễn ra tại thủ đô Manila, Philippines vào cuối tháng 10 này!\n\nVô cùng tự hào về bản thân vì đã DÁM làm những điều chưa bao giờ dám làm để có được ĐỢI như ngày hôm nay. Mình sẽ tiếp tục kiên trì đưa những lát cắt đời sống chân thực của người ngồi xe lăn vào các dự án phim sắp tới.\n\nDù con đường phía trước còn nhiều thử thách, nhưng được làm điều mình yêu thích, được gửi gắm những trăn trở và khát khao hòa nhập vào từng thước phim, đó đã là phần thưởng ngọt ngào nhất của đam mê.',3,1,1,'published','2026-10-02 09:00:00','Phim ngắn ĐỢI lọt Chung kết Inspiring Asia 2026 tại Manila','Hành trình tự hào khi phim ngắn ĐỢI trở thành 1 trong 2 đại diện Việt Nam bước vào Chung kết Inspiring Asia 2026 tại Manila, Philippines.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(9,'nguoi-khuyet-tat-dong-phim-va-hien-tuong-tu-y-thuc-khach-quan','Người khuyết tật lần đầu đóng phim: Sự tự ý thức khách quan','Cảm giác người khuyết tật lần đầu đóng phim và xem lại phim mình đóng: Ngại ơi là ngại. Và góc nhìn tâm lý học về sự tự ý thức khách quan.','Cảm giác Người Khuyết Tật lần đầu đóng phim và xem lại phim mình đóng sẽ như thế nào?\n\nLà ngại. Ngại ơi là ngại. Ngại tới bến. Ngại muốn độn thổ! Xem chưa đến 2 giây đã PHỤP, tắt máy, không dám xem tiếp nữa. May mà lúc đó chỉ có một mình mình ngồi xem, chứ không chắc chết vì ngại mất.\n\n![An ngồi trước con phố đông đúc trong phim ngắn ĐỢI](/uploads/2026/10/2aobor5evyphipg5ezn6ushayo6aaonoieebpx6e8-55e675-960.webp)\n*Khoảnh khắc nhân vật An đối diện với thế giới bên ngoài trong ĐỢI.*\n\n## \"Sự tự ý thức khách quan\" trong tâm lý học\n\nSau khi trấn tĩnh lại, mình mới thử tìm hiểu xem tại sao cảm xúc ngượng ngùng ấy lại mãnh liệt đến thế. Hóa ra trong tâm lý học, hiện tượng này được gọi là **“sự tự ý thức khách quan” (Objective Self-Awareness)**.\n\nBình thường, chúng ta nhìn nhận bản thân từ bên trong cơ thể (từ góc nhìn chủ quan thứ nhất). Nhưng khi đứng trước màn ảnh kia, lần đầu tiên mình nhìn nhận bản thân dưới ánh mắt của một người quan sát bên ngoài. \n\nKhi nhìn thấy chính mình trong khung hình, não bộ sẽ tự động so sánh con người thực tế trên phim với hình tượng lý tưởng mà bấy lâu nay mình vẫn tưởng tượng về bản thân. Mình nghĩ mình đã diễn thế này, biểu cảm thế kia, nhưng máy quay lại ghi được một phiên bản hoàn toàn khác. \n\nChính khoảng cách giữa hai phiên bản ấy tạo nên cảm giác ngượng ngùng đến mức chỉ muốn đào một cái hố để chui xuống.\n\n## Khi biên kịch kiêm diễn viên ngồi bắt lỗi chính mình\n\nChưa kể khi xem lại phim mình đóng, mình không thể nào thưởng thức bộ phim như một khán giả bình thường được nữa. Khán giả xem sẽ theo dõi câu chuyện, thấu cảm số phận nhân vật và mạch cảm xúc. Còn mình thì cứ chăm chăm mổ xẻ từng chi tiết nhỏ: \n\n- *Ơ, cảnh này sao mặt đơ thế nhỉ?*\n- *Sao lại cau mày chỗ này, đoạn này phải cụp mắt buồn mới đúng chứ!*\n- *Eo ơi, góc máy này nhìn mặt mình lên hình sao to vậy...*\n\nCứ thế, việc ngồi bắt lỗi bản thân chiếm trọn 90% thời gian xem, thành ra cứ ngại ngùng mãi không thôi. \n\nNhưng rồi sau những bối rối ban đầu, mình học được cách bao dung hơn với bản thân. Bước ra khỏi vùng an toàn để thử sức ở một vai trò hoàn toàn mới đã là một chiến thắng. Có lẽ, hành trình học cách yêu thương cả những nét vụng về của chính mình trên khung hình cũng là một phần quan trọng để người nghệ sĩ trưởng thành.',9,1,1,'published','2026-09-24 16:00:00','Người khuyết tật lần đầu đóng phim và sự tự ý thức khách quan','Cảm giác lần đầu xem lại phim mình đóng của biên kịch Thanh Thanh và lý giải hiện tượng \"sự tự ý thức khách quan\" trong tâm lý học.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(10,'du-an-dien-anh-dau-tay-dua-con-den-tu-coi-am-top-7-s2s','Dự án điện ảnh đầu tay \"Đứa con đến từ cõi âm\" lọt Top 7 From Script to Screen','Chiếc thông báo chính thức dự án phim điện ảnh đầu tay \"Đứa con đến từ cõi âm\" lọt Top 7 From Script to Screen mùa 1 và khát khao không bao giờ tắt.','Một chiếc thông báo chính thức: dự án phim điện ảnh đầu tay **“Đứa con đến từ cõi âm”** của mình đã chính thức lọt vào **Top 7 FROM SCRIPT TO SCREEN MÙA 1**!\n\n## Chuyến đi đêm đông Hà Nội và thất bại đầu đời\n\nVới dự án “Đứa con đến từ cõi âm”, đây là ý tưởng phim mình viết từ năm 2024 với mục đích mang đi gặp anh Đức Thịnh và chị Thanh Thúy. \n\nĐó là một chuyến đi mà mình không bao giờ quên, giữa một ngày đông Hà Nội rét buốt. Đến lúc gặp được anh chị thì trời đã về đêm. Dù gió lạnh cắt da nhưng lòng mình lại vô cùng ấm áp vì hai anh chị ngoài đời thực rất gần gũi, chân thành và dễ thương. \n\nNhờ sự cởi mở ấy, mình đã có thể tự tin trình bày về ý tưởng dự án. Nhưng khi ấy, kiến thức viết kịch bản của mình vẫn còn quá non và xanh, cấu trúc đầy lỗ hổng nên việc anh chị từ chối là điều hoàn toàn dễ hiểu.\n\n![Toàn cảnh sự kiện vinh danh các nhà làm phim trẻ](/uploads/2026/10/2aobor5evwrqnr0omubrhfwcjrvca5l2s7ydft4a6-29aec5-960.webp)\n*Mỗi dự án là một nấc thang trưởng thành của người viết kịch bản.*\n\n## Khát khao 200% và cơ hội quý giá tại S2S\n\nDù chuyến đi chào mời dự án đầu tiên đó thất bại, nhưng mình lại gom nhặt được vô vàn trải nghiệm quý giá, và trên hết là một khát khao mãnh liệt: **phải hoàn thành bằng được câu chuyện này.**\n\nÝ tưởng ấy cứ đeo bám tâm trí mình suốt nhiều tháng trời. Cứ mỗi lần học thêm được một kiến thức mới về cấu trúc 3 hồi, về cách xây dựng động cơ nhân vật hay cài cắm xung đột, mình lại lôi đề cương ra vá víu vào những chỗ khiếm khuyết.\n\nĐến khi gửi dự án cho S2S Program, thực sự đọc lại, dù là người đẻ ra nó nhưng mình vẫn thấy bản thân mới chỉ đạt được khoảng 60% độ cuốn hút mong muốn. Tuy vậy, điều đó không làm mình bớt tin vào tiềm năng của tác phẩm. \n\nNgược lại, chính vì nhìn thấy rõ những khoảng trống cần hoàn thiện, mình càng khao khát có cơ hội được lắng nghe góp ý từ hội đồng giám khảo tại buổi pitching. Chắc chắn mình sẽ mang theo 200% ngọn lửa đam mê để bảo vệ đứa con tinh thần này.\n\nĐặc biệt, mình vô cùng biết ơn Ban tổ chức S2S Program đã tạo điều kiện tối đa để mình được tham gia pitching online (do vấn đề sức khỏe và điều kiện di chuyển xe lăn vào TP.HCM quá phức tạp). Sự thấu hiểu và hỗ trợ nhân văn của BTC chính là nguồn động viên to lớn để mình tiếp tục kiên trì theo đuổi con đường biên kịch điện ảnh chuyên nghiệp.',6,1,1,'published','2026-08-05 11:00:00','Đứa con đến từ cõi âm lọt Top 7 From Script to Screen','Hành trình ấp ủ dự án phim điện ảnh đầu tay \"Đứa con đến từ cõi âm\" của biên kịch Thanh Thanh và niềm vui khi lọt Top 7 cuộc thi From Script to Screen.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(11,'hoc-cach-lam-pitch-deck-tu-breaking-bad','Học cách làm Pitch Deck từ show pitch của Breaking Bad: Bí quyết giữ chân người nghe','Một ngày cạy cục mày mò tìm hiểu pitching deck vô tình đọc được show pitch phim Breaking Bad: Không kể hết nhưng khiến người nghe muốn biết phần còn lại.','Một ngày cạy cục mày mò tìm hiểu về kỹ thuật làm Pitching Deck, mình vô tình đọc được tài liệu show pitch của series phim truyền hình huyền thoại **Breaking Bad**. Đọc xong chỉ biết thốt lên: Đỉnh cao thực sự!\n\nBộ pitch deck được trình bày vô cùng mượt mà, gợi mở, gây tò mò tột độ và đúng chuẩn nguyên tắc vàng trong nghệ thuật chào bán ý tưởng: \n\n> **\"Không kể hết câu chuyện, nhưng khiến người nghe khao khát muốn biết phần còn lại của câu chuyện.\"**\n\n![Chia sẻ về kỹ năng pitching và phát triển dự án phim](/uploads/2026/10/2aobor5evw8tqadifc1aysdsulfim4q8lvscssvw5-d598c2-960.webp)\n*Một pitch deck xuất sắc là chiếc cầu nối biến ý tưởng trên giấy thành hiện thực trường quay.*\n\n## 3 bài học đắt giá từ bản pitch Breaking Bad\n\nQua bản pitch deck kinh điển ấy, mình rút ra được ba bài học cốt tử mà bất kỳ biên kịch nào cũng cần ghi nhớ khi chuẩn bị hồ sơ gọi vốn làm phim:\n\n### 1. Hook (Móc câu) phải xuất hiện ngay trong 30 giây đầu tiên\nĐừng mở đầu bằng những triết lý nhân sinh dài dòng. Hãy ném người nghe vào ngay tình huống ngặt nghèo và nghịch lý nhất của nhân vật chính: Một thầy giáo dạy hóa học hiền lành, phát hiện ung thư phổi giai đoạn cuối và quyết định nấu chất cấm để kiếm tiền để lại cho gia đình. Một tiền đề (premise) quá mạnh mẽ khiến người nghe lập tức bị cuốn vào.\n\n### 2. Thiết lập động cơ nhân vật không thể đảo ngược (High Stakes)\nKhi pitching, điều nhà sản xuất quan tâm nhất là: *Tại sao nhân vật bắt buộc phải hành động như vậy mà không thể chọn con đường khác?* Nếu nhân vật có lối thoát dễ dàng, câu chuyện sẽ trở nên nhạt nhẽo. Cọc cược (stakes) phải đủ cao: sự sống còn, danh dự, tình yêu hoặc sự tự do.\n\n### 3. Để lại khoảng trống cho trí tưởng tượng (Cliffhanger)\nRất nhiều bạn mới làm hồ sơ pitching thường mắc lỗi cố kể hết toàn bộ plot twist từ đầu đến cuối phim. Hậu quả là bản pitch dài lê thê và làm mất đi cảm giác hồi hộp. Hãy dừng lại ở điểm giao thoa căng thẳng nhất, để nhà sản xuất phải tự đặt câu hỏi: *“Rồi chuyện gì sẽ xảy ra tiếp theo?”*. Khi họ hỏi câu đó, bạn đã thành công 50% trong buổi pitching.\n\nHọc được một kiến thức mới, hiểu sâu hơn về nghề mỗi ngày chính là niềm vui lớn nhất trên bàn viết của mình!',5,2,1,'published','2026-09-15 15:30:00','Học cách làm Pitch Deck từ show pitch của Breaking Bad','Bí quyết xây dựng Pitch Deck kịch bản phim hấp dẫn lấy cảm hứng từ show pitch kinh điển của Breaking Bad: Không kể hết nhưng khiến người nghe khao khát.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(12,'de-co-8-phut-phim-doi-bay-mau-3-thang-thanh-xuan','Để có 8 phút phim ĐỢI: Bay màu gần 3 tháng thanh xuân và bài học trọn vẹn','Chỉ một tấm poster thôi nhưng để có được nó, mình đã bay màu gần 3 tháng thanh xuân cho 8 phút phim với đủ mọi cung bậc cảm xúc.','Cuối cùng cũng nhìn thấy poster phim ngắn ĐỢI chính thức ra đời!\n\nChỉ một tấm hình đơn giản với chữ ĐỢI lặng lẽ hiện lên trên nền ngã tư phố xá, nhưng để có được hình ảnh này, mình đã đánh đổi bằng gần 3 tháng thanh xuân đầy trăn trở và nỗ lực.\n\n![Poster chính thức của phim ngắn ĐỢI](/uploads/2026/10/2aobor5evzroaxpvhrzgfdv5e6hek6icnghrztda11-746caa-960.webp)\n*Tấm poster đánh dấu sự hoàn thành của một dự án trầy da tróc vảy.*\n\n## Dòng thời gian \"bay màu thanh xuân\" cho 8 phút phim\n\nNgồi bấm ngón tay tính lại toàn bộ hành trình làm phim:\n\n- **2 tuần** vò đầu bứt tai tìm ý tưởng, ngước nhìn các tác phẩm kinh điển như *Stutterer* hay *This is John* để tìm kiếm một góc nhìn nhân văn mà khác biệt.\n- **Hơn 1 tháng** viết, gọt giũa kịch bản từng câu thoại và chuẩn bị hồ sơ dự thi gửi ban tổ chức.\n- **7 ngày** cày nát gần 30 bộ phim ngắn đủ thể loại mỗi sáng để phân tích cấu trúc làm hồ sơ pitching.\n- **1 ngày** pitching trong hồi hộp đến nghẹt thở, ngồi chờ đến lượt ở STT 4 đúng nghĩa tinh thần của từ \"ĐỢI\".\n- **2 tuần** ngồi thảo luận, tranh luận và chỉnh sửa kịch bản cùng ekip sản xuất để biến những con chữ trên trang giấy thành giải pháp khả thi ngoài đời thực.\n- **2 ngày** lăn lộn thực tế trên trường quay dưới cái nắng Sài Gòn bỏng rát, hai tay điều khiển xe lăn đỏ ửng vì cháy nắng.\n\n![Khung hình nhân vật An đơn độc giữa bậc thang](/uploads/2026/10/2aobor5evvogdriu1ftcphalicn2jbprizyigwag4-ff2be1-960.webp)\n*Hai ngày quay nắng rát trên đường phố Sài Gòn để lột tả chân thực từng cảm xúc.*\n\n## Đi cùng một kịch bản từ trang giấy đến màn ảnh\n\nTính ra, để có được 8 phút phim ngắn ngủi trên màn hình, mình đã mất gần 3 tháng ròng rã. Chưa kể những chuỗi ngày mất ngủ vì lo lắng, những lúc hồi hộp chờ đợi kết quả duyệt giấy phép, hay những khi niềm vui vỡ òa khi hoàn thành một cảnh quay khó.\n\nNhưng cũng nhờ dự án này, đây là lần đầu tiên trong đời mình được đi cùng một kịch bản từ thuở còn là vài dòng ghi chú nguệch ngoạc cho đến khi nó thực sự cất tiếng nói trên màn ảnh lớn. \n\nMột hành trình đầy trải nghiệm, trầy da tróc vảy nhưng ngập tràn niềm tự hào vì bản thân đã kiên cường đi được đến tận cùng của ước mơ.',11,1,1,'published','2026-09-18 08:00:00','Để có 8 phút phim ĐỢI: Bay màu gần 3 tháng thanh xuân','Dòng thời gian sản xuất phim ngắn ĐỢI: 3 tháng trầy da tróc vảy từ ý tưởng, pitching, chỉnh sửa đến 2 ngày bỏng rát trên trường quay của Thanh Thanh.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(13,'khi-trang-sach-chien-tranh-nuoi-duong-tam-hon-bien-kich','Từ \"Tuổi thơ dữ dội\" đến \"Vượt Côn Đảo\": Khi trang sách nuôi dưỡng tâm hồn người viết','Cũng vì mê Tuổi Thơ Dữ Dội mà Vượt Côn Đảo đã cập bến. Bé đọc thấy khô khan, lớn lên sau 20 năm bị cuộc đời sàng sảy lại muốn tìm đọc để hiểu và thương.','Cũng vì quá mê cuốn *Tuổi Thơ Dữ Dội* của bác Phùng Quán mà hôm nay, cuốn *Vượt Côn Đảo* đã chính thức cập bến bàn đọc sách của mình ở Tản Hồng.\n\nNgày bé, mỗi lần mở sách giáo khoa mà gặp phải mấy bài tập đọc về chiến tranh, về lịch sử kháng chiến, khi đó đầu óc non nớt chỉ thấy mọi thứ sao mà khô khan, khó nhớ, tưới thế nào cũng không thấm nổi vào đầu.\n\nGiờ thì, sau hơn hai mươi năm bị cuộc đời sàng sảy qua bao thăng trầm, biến cố và cả những giới hạn thể xác, mình lại có xu hướng tìm đọc những cuốn tiểu thuyết về chiến tranh và thân phận con người.\n\n![An kiên định tiến về phía trước giữa dòng đời](/uploads/2026/10/2aobor5evykmmffp4mlnvammpa8m4vgw7cwd4jms9-2908cf-960.webp)\n*Đọc để hiểu, để thương và để tự nhắc nhở bản thân không bao giờ được bỏ cuộc.*\n\n## Đọc để hiểu, để thương và để cố gắng\n\nKhi đọc về những con người đã đi qua mưa bom bão đạn, chịu đựng những hy sinh cùng cực trong xà lim Côn Đảo hay những đứa trẻ can trường của Đội thiếu niên trinh sát Trung đoàn Trần Cao Vân, mình nhận ra nỗi đau và những khó khăn của bản thân hôm nay thật nhỏ bé biết bao.\n\nBé không thể hiểu được, lớn lên lại muốn tìm về đọc để hiểu, để thương và tự thấy mình phải nỗ lực, cố gắng nhiều hơn nữa mỗi ngày.\n\n## Vốn sống – \"kho báu\" vô giá của người viết kịch bản\n\nĐối với một người làm nghề viết lách, đặc biệt là viết kịch bản phim, trang sách chính là người thầy vĩ đại nhất nuôi dưỡng vốn sống và chiều sâu nội tâm. \n\nMột biên kịch không thể chỉ viết bằng kỹ thuật hay mẹo mực cấu trúc. Nếu tâm hồn người viết cạn kiệt, câu chuyện sẽ trở nên rỗng tuếch. Việc đọc sâu, suy ngẫm về những số phận kiên cường trong văn học giúp mình mở rộng biên độ cảm xúc, học cách thấu cảm với những nỗi đau thầm lặng và từ đó, thổi vào nhân vật của mình một sức sống chân thực, can trường nhất.',8,2,1,'published','2026-09-12 17:00:00','Khi trang sách chiến tranh nuôi dưỡng tâm hồn biên kịch','Tản văn về việc đọc sách của biên kịch Thanh Thanh: Từ Tuổi thơ dữ dội đến Vượt Côn Đảo, trang sách nuôi dưỡng chiều sâu và vốn sống cho người cầm bút.','vi','manual',NULL,0,NULL,'2026-10-14 06:03:48','2026-10-14 06:03:48'),(14,'lan-dan-tim-nha-tai-tro-cho-phim-doi-khi-bien-kich-tu-go-cua','Lận đận tìm nhà tài trợ cho phim ĐỢI: Khi biên kịch phải tự \"gõ cửa\" để được đóng vai chính','Nhiều người xem phim xong bảo: \"Mặt bà cá tính quá, phim sau lại đóng nhé!\". Mình cười đáp: \"Bà nói vậy tui lại thấy cực, phải lận đận kiếm được nhà tài trợ mới có vai chính được chứ!\".','Mấy hôm trước sau khi công bố thông tin phim ngắn **ĐỢI (WAITING)** chính thức lọt vào **Top 7 Grand Finalists của Inspiring Asia Micro Film Festival 2026**, một người bạn nhắn tin cho mình đùa:\n\n> *\"Nét mặt bà cá tính mà, chờ phim khác có bà đóng tiếp nha :)))\"*\n\nMình chỉ biết thả icon cười mếu rồi đáp:\n\n> *\"Bà nói câu đấy tui lại thấy vất vả rồi. Lận đận mãi mới kiếm được nhà tài trợ, mới vào vai chính được đó bà ơi!\"*\n\nCâu đùa nghe vui tai, nhưng ai từng làm phim độc lập – đặc biệt là phim ngắn đầu tay – mới thấm thía cái giá của hai chữ **\"nhà tài trợ\"**.\n\n![Poster Top 7 Grand Finalists Inspiring Asia 2026](/uploads/2026/10/inspiring-asia-2026-grand-finalists-waiting-doi-7d0d67-960.webp)\n*Phim ngắn ĐỢI (WAITING) vinh dự nằm trong Top 7 Grand Finalists tại Inspiring Asia Micro Film Festival 2026.*\n\n## Viết kịch bản là bay bổng, tìm tài trợ là bài test độ \"lì lợm\"\n\nNhiều bạn trẻ hỏi mình: *“Chị ơi, viết xong kịch bản hay rồi thì gửi cho ai để có tiền quay?”*. Mình hay cười bảo: *“Viết xong kịch bản mới chỉ là đi được 20% chặng đường thôi. 80% còn lại là đi gõ cửa từng nơi để chứng minh kịch bản ấy xứng đáng được sống”*.\n\nVới một người ngồi xe lăn như mình, hành trình đó nhân đôi phần chông gai:\n1. **Ranh giới giữa nghệ thuật và sự thương hại:** Khi mình ngồi xe lăn xuất hiện tại các buổi pitching hay gửi email xin tài trợ, nỗi sợ lớn nhất là người ta gật đầu vì... thương hại. Mình không muốn ai rót tiền cho phim *ĐỢI* chỉ vì “giúp đỡ một người khuyết tật”. Mình muốn họ tài trợ vì câu chuyện của An đủ sức nặng, vì cấu trúc kịch bản chặt chẽ và vì thông điệp nghệ thuật có giá trị chạm đến số đông.\n2. **Những chiếc email không hồi âm:** Hàng chục bộ hồ sơ gửi đi, từ các quỹ văn hóa, các doanh nghiệp cho đến những người quen biết. Có nơi từ chối thẳng thắn, có nơi im lặng vô thời hạn. Đã có những buổi tối nhìn bản thảo kịch bản, mình tự hỏi: *Liệu có phải mình đang quá viển vông?*\n\n![Hậu trường phim ngắn ĐỢI](/uploads/2026/10/2aobor5evvogdriu1ftcphalicn2jbprizyigwag4-ff2be1-960.webp)\n*Một khung hình xúc động trong phim ngắn ĐỢI: An đối diện với những bậc thang ngăn cách.*\n\n## Khi cái gật đầu đầu tiên xuất hiện\n\nBộ phim sẽ không thể thành hình nếu không có sự lì lợm của cả hai chị em: mình và đạo diễn Ngô Linh Chi. Bọn mình gom góp từng cơ hội nhỏ nhất. Từ những buổi pitching căng thẳng trước đạo diễn Trịnh Đình Lê Minh và chị Phạm Thị Hảo, đến từng khoản hỗ trợ thiết bị, phục trang, bối cảnh từ những người đồng hành thấu hiểu.\n\nMình nhận ra một điều quan trọng: **Nhà tài trợ không đầu tư vào sự than thở, họ đầu tư vào ngọn lửa đam mê và sự chuẩn bị kỹ lưỡng.** Khi bạn chuẩn bị một Pitch Deck chỉn chu, chứng minh được từng khung hình đều được tính toán và tâm huyết, cánh cửa sẽ mở ra.\n\n## Quả ngọt từ sự kiên trì\n\nGiờ đây, khi nhìn thấy poster của *ĐỢI* đứng cạnh những tác phẩm xuất sắc đến từ Mông Cổ, Trung Quốc, Philippines trong bảng đề cử Grand Finalists tại Manila, mình thầm cảm ơn những ngày tháng “lận đận đi xin cơm” ấy.\n\nNếu không có sự kiên trì gõ cửa từng nhà tài trợ, nhân vật An sẽ mãi chỉ nằm lại trên những trang giấy A4. Và cô gái ngồi xe lăn ngoài đời thực cũng sẽ không bao giờ có cơ hội đứng trước ống kính máy quay để kể câu chuyện của chính cuộc đời mình.\n\nLàm phim khó lắm, nhưng nếu không dấn thân, bạn sẽ không bao giờ biết được giới hạn của mình nằm ở đâu!',16,1,1,'published','2026-10-14 06:15:00','Hậu trường tìm tài trợ cho phim ĐỢI | Thanh Thanh','Chuyện thật hậu trường phim ĐỢI: Biên kịch ngồi xe lăn đi gõ cửa từng nhà tài trợ, bài học lì lợm và quả ngọt tại Chung kết Inspiring Asia 2026.','vi','facebook',NULL,0,NULL,'2026-10-14 08:27:16','2026-10-14 08:29:14'),(15,'10-nam-nam-liet-giuong-va-chiec-may-tinh-mo-ra-cuoc-doi-bien-kich','10 năm nằm liệt giường và chiếc máy tính mở ra cuộc đời một biên kịch','Gần 10 năm trời ròng rã, bố mẹ đưa mình đi khắp nơi chạy chữa. Thần chết từng tìm đến nhưng không mang mình đi, đổi lại lấy đi đôi chân, sức khỏe và sự tự do. Cho đến năm 25 tuổi, một chiếc máy tính xuất hiện...','Trong phần tiểu sử của trang cá nhân, mình chọn đặt lại một câu nói của Kito Aya trong cuốn nhật ký *Một lít nước mắt*:\n\n> *\"Chúa đã khiến mình trở nên tàn tật. Đó là vì Người tin rằng mình có khả năng chịu đựng.\"*\n\nĐể có thể mỉm cười thanh thản khi nhắc lại câu nói ấy, mình đã phải đi qua một thập kỷ tối tăm nhất của tuổi trẻ – gần 10 năm nằm liệt giường và từng nghĩ đến việc kết thúc tất cả.\n\n![Biên kịch Thanh Thanh bên chiếc xe lăn](/uploads/2026/10/2aobor5evxjuzmsmaqvetvecvklcoeao1qwg84ao7-2ba0ce-960.webp)\n*Biên kịch Thanh Thanh: \"Không để người khác quyết định giới hạn của bản thân.\"*\n\n## Tuổi 15 và tiếng sét đánh ngang tai\n\nVới nhiều người, tuổi 15 là độ tuổi đẹp nhất của những ước mơ học trò. Nhưng với mình, tuổi 15 là bắt đầu của những cơn sốt triền miên và các khớp sưng nóng đỏ đau. Căn bệnh viêm khớp dạng thấp ập đến quá nhanh.\n\nBan đầu, mình chỉ nghĩ uống thuốc vài ngày rồi sẽ khỏi. Vừa nằm viện, mình vừa nhờ bạn bè, bố mẹ cõng đến trường. Nhưng rồi chiếc áo đồng phục học sinh dần bị thay thế hoàn toàn bằng bộ quần áo bệnh nhân. Mình nằm liệt giường, không thể tự xúc cơm ăn, không thể tự chải đầu, tắm giặt hay làm bất cứ sinh hoạt cá nhân nào.\n\nGần 10 năm ròng rã, bố mẹ đưa mình đi khắp các bệnh viện đông tây y chạy chữa. Thần chết từng tìm đến nhưng không mang mình đi, đổi lại lấy đi sức khỏe, hình hài, đôi tay, đôi chân và cả sự tự do của một cô gái tuổi đôi mươi. Trong bốn bức tường ngột ngạt, đã có những đêm mình rơi vào đáy sâu tuyệt vọng.\n\n## Bước ngoặt năm 25 tuổi: Chiếc máy tính và hai người bạn\n\nNăm 25 tuổi, một chiếc máy tính kết nối internet xuất hiện trong căn phòng nhỏ. Qua mạng xã hội, mình may mắn làm quen với hai người bạn đặc biệt: một người mở ra cho mình kho tàng sách, và một người dạy cho mình cách nhìn nhận giá trị của bản thân.\n\nTừ khoảnh khắc ấy, chiếc giường bệnh không còn là nơi giam cầm, mà biến thành một **studio sáng tạo**:\n- **Sách trở thành người thầy vĩ đại:** Mình đọc ngấu nghiến từ văn học chiến tranh, triết học đến kỹ thuật viết kịch bản điện ảnh phương Tây.\n- **Bàn phím là đôi cánh tự do:** Dù các ngón tay co cứng, đau buốt, mình vẫn kiên nhẫn gõ từng con chữ. Mình tự nhủ: *“Dù không còn đôi chân lành lặn, mình vẫn còn trí tuệ, một tâm hồn nhạy cảm và một trái tim khát khao đồng cảm với con người”*.\n\n![Thanh Thanh chia sẻ tại buổi tọa đàm](/uploads/2026/10/2aobor5evw8tqadifc1aysdsulfim4q8lvscssvw5-d598c2-960.webp)\n*Thanh Thanh chia sẻ về hành trình tự học viết kịch bản từ số 0 tại buổi tọa đàm.*\n\n## Con đường không trải hoa hồng\n\nKhởi đầu với nghề biên kịch, mình nhận vô số lời từ chối. Hàng chục email gửi đề cương kịch bản đi mà không nhận lại một dòng hồi âm. Nhưng một người từng chiến thắng tử thần thì không có lý do gì để đầu hàng trước những lời từ chối bản thảo.\n\nThành quả bắt đầu đơm hoa:\n- **Năm 2019:** Giải Nhì cuộc thi sáng tác truyện tranh với *Thóc và Đậu*.\n- **Năm 2020:** Giải Ba *Nhà viết kịch tài ba* trong dự án phòng ngừa bạo lực học đường của Good Neighbors International.\n- **Năm 2023:** Giải Đặc biệt cuộc thi viết *Vượt lên số phận*.\n- **Năm 2024:** Giải Nhất cuộc thi sáng tác kịch bản thiếu nhi do Nhà hát Tuổi Trẻ và Nhà hát Sangsang Maru (Hàn Quốc) tổ chức với vở *Ước mơ của em*.\n- **Năm 2026:** Phim ngắn *ĐỢI* lọt Chung kết Inspiring Asia tại Manila.\n\n## 90% còn lại là cách chúng ta đón nhận\n\nXuất hiện trên chương trình *Trạm yêu thương* của VTV1, mình đã chia sẻ một điều mà mình luôn khắc cốt ghi tâm:\n\n> *\"Cuộc sống có 10% là những điều số phận đặt để, nhưng 90% còn lại phụ thuộc vào cách chúng ta đón nhận và bước tiếp.\"*\n\nĐừng bao giờ để chiếc xe lăn, hoàn cảnh nghèo khó hay bất kỳ rào cản nào định nghĩa giới hạn của bạn. Chỉ cần đôi tay còn có thể chạm vào bàn phím và trái tim còn rung động trước cuộc đời, bạn vẫn luôn có thể viết nên câu chuyện vĩ đại của chính mình.',7,3,1,'published','2026-10-14 06:30:00','10 năm liệt giường & hành trình biên kịch | Thanh Thanh','Hành trình vượt qua nghịch cảnh: Từ cô gái 15 tuổi nằm liệt giường vì viêm khớp dạng thấp đến biên kịch đoạt giải quốc tế nhờ chiếc máy tính và nghị lực phi thường.','vi','facebook',NULL,0,NULL,'2026-10-14 08:27:16','2026-10-14 08:27:16'),(16,'60-phut-cai-nghien-man-hinh-nguoi-ngoi-xe-lan-hoc-cach-thong-dong-tan-huong','60 phút \"cai nghiện\" màn hình: Khi người ngồi xe lăn học cách thong dong tận hưởng cuộc sống','1 giờ làm phục vụ 25k/h, nhưng cũng trong 1 giờ đó bạn được trả 50k khi bỏ hết thiết bị, chỉ đọc sách sâu và viết cảm nhận. Sau những tuần cày kịch bản căng não, mình học cách \"cắt màn hình\" để tìm lại chính mình.','Mấy ngày trước lướt mạng, mình tình cờ đọc được một tấm áp-phích thú vị của một thư viện trường đại học:\n\n> *\"50K/1H – Đọc sách nhận thưởng? Thật đó! 60 phút đọc sâu: Một giờ tạm rời màn hình, gửi thiết bị điện tử tại quầy, chọn góc chill và tập trung đọc sách, ghi lại cảm nhận...\"*\n\nMột phép so sánh hóm hỉnh đặt ra: 1 giờ làm phục vụ bưng bê được 25.000đ, nhưng trong 1 giờ chỉ ngồi yên đọc sách và chiêm nghiệm lại được trả gấp đôi. Dù chỉ là một chiến dịch khuyến đọc, nó đánh trúng một \"căn bệnh thời đại\" mà chính những người làm nghề sáng tạo như mình mắc phải: **nghiện màn hình và kiệt sức tinh thần.**\n\n![Khoảnh khắc bình yên bên trang sách](/uploads/2026/10/2aobor5evufktut5yfbobsfbyisynny8p8zsr8l21-7a2368-960.webp)\n*Khoảnh khắc bình yên bên ban công: Khi những con chữ trên trang sách giấy nạp lại năng lượng cho tâm hồn.*\n\n## \"Nghẽn mạch\" sáng tạo vì ánh sáng xanh\n\nNhững ai viết kịch bản đều biết cảm giác này: bạn ngồi trước laptop 12 đến 14 tiếng một ngày, mở cùng lúc 20 tab tư liệu, vừa gõ vừa canh tin nhắn, vừa lướt mạng xã hội xem xu hướng. Mắt cay xè, thái dương giật từng cơn, các ngón tay mỏi nhừ. \n\nVà tệ nhất là: **chữ nghĩa bắt đầu trở nên xơ cứng.**\n\nKhi não bộ bị quá tải bởi luồng thông tin ngắn, nông và nhanh trên mạng xã hội, khả năng lắng đọng để thấu cảm nhân vật bị triệt tiêu. Nhân vật trong kịch bản của bạn bắt đầu nói những câu thoại vô hồn, rập khuôn và thiếu nhịp thở đời thực.\n\nĐó là lúc mình tự ra lệnh cho bản thân: **Phải \"cai nghiện\" màn hình ngay lập tức!**\n\n## 60 phút gửi điện thoại và sự kỳ diệu của trang sách giấy\n\nMình bắt đầu áp dụng quy tắc 60 phút không thiết bị:\n- Tắt nguồn điện thoại hoặc để hẳn ở một phòng khác.\n- Chọn một góc ban công đón gió hoặc một góc quán quen yên tĩnh.\n- Mở một cuốn sách giấy thật sự – ngửi mùi giấy mới, lật từng trang và đọc sâu.\n\nKhi không còn tiếng ting ting thông báo, thời gian như trôi chậm lại. Tâm trí được giải phóng khỏi áp lực deadline. Từng câu chữ trong trang sách bắt đầu ngấm vào suy nghĩ, gợi mở những góc nhìn nhân vật mà trước đây ngồi vắt óc trước màn hình laptop không thể nào nghĩ ra được.\n\n![Thanh Thanh cùng cuốn sách yêu thích](/uploads/2026/10/2aobor5evufmujpttsu0sdq2zft0r4qj2wpbhc2c2-645a2f-960.webp)\n*Sách không chỉ là người thầy mở rộng tri thức mà còn là liều thuốc chữa lành cho tâm trí sau những giờ làm việc căng thẳng.*\n\n## Người khuyết tật cũng có quyền thong dong tận hưởng\n\nNgười ta hay gắn hình ảnh người khuyết tật với hai thái cực: hoặc là bi kịch đáng thương, hoặc là tấm gương \"nghiến răng vượt khó\". Rất ít người nghĩ rằng người ngồi xe lăn cũng cần và cũng có quyền tận hưởng cuộc sống theo cách tao nhã nhất.\n\nTận hưởng của mình đơn giản lắm:\n- Là một buổi chiều thu lăn xe dưới hàng cây râm mát, cảm nhận làn gió mơn man trên má.\n- Là nhấp một ngụm trà thảo mộc ấm, ngắm nhìn nhịp sống phố xá hối hả trôi qua trước mắt.\n- Là dành trọn vẹn 1 giờ để đọc một chương sách hay mà không bị bất kỳ ai làm phiền.\n\nVới một người viết kịch bản, **tâm có tĩnh thì chữ mới sâu.** Học cách nghỉ ngơi, buông bỏ thiết bị và thong dong tận hưởng cuộc đời chính là cách tốt nhất để nuôi dưỡng ngòi bút của bạn đi được đường dài.',1,2,1,'published','2026-10-14 06:45:00','60 phút cai nghiện màn hình & nghệ thuật sống | Thanh Thanh','Sau những ngày cày kịch bản cật lực, biên kịch ngồi xe lăn học cách tắt điện thoại, đọc sách sâu và thong dong tận hưởng từng nhịp thở của cuộc sống.','vi','facebook',NULL,0,NULL,'2026-10-14 08:27:16','2026-10-14 08:27:16'),(17,'viet-kich-ban-thieu-nhi-khi-co-be-nhat-linh-buoc-ra-tu-noi-dau','Viết kịch bản cho thiếu nhi: Khi cô bé Nhất Linh bước ra từ nỗi đau của chính mình','Nhân vật cô bé Nhất Linh trong vở nhạc kịch \"Ước mơ của em\" mang trong mình nỗi đau bệnh tật, nhưng không bao giờ từ bỏ hy vọng. Làm sao để viết cho trẻ em mà không rơi vào bi kịch hóa?','Năm 2024, khi kịch bản nhạc kịch **\"Ước mơ của em\"** được xướng tên ở giải cao nhất cuộc thi sáng tác kịch bản cho trẻ em do Nhà hát Tuổi Trẻ phối hợp cùng Nhà hát Sangsang Maru (Hàn Quốc) tổ chức, nhiều đồng nghiệp hỏi mình:\n\n> *\"Làm sao một người phải chịu đựng những cơn đau thể xác triền miên như chị lại có thể viết nên một câu chuyện thiếu nhi trong trẻo và hồn nhiên đến vậy?\"*\n\nCâu trả lời nằm ở nhân vật chính của vở kịch – cô bé **Nhất Linh**. Một nhân vật bước ra từ chính tuổi thơ và những vết thương sâu kín nhất của cuộc đời mình.\n\n![Lễ trao giải sáng tác kịch bản](/uploads/2026/10/2aobor5evuwgbpigsfaezmu1nfyaxk3gozy7rrzq3-aad272-960.webp)\n*Khoảnh khắc vinh danh trên sân khấu: Khi những câu chuyện chân thành chạm tới trái tim ban giám khảo quốc tế.*\n\n## Nhất Linh: Chiếc bóng tuổi thơ và ngọn lửa ước mơ\n\nTrong kịch bản, Nhất Linh là một cô bé mang trong mình căn bệnh hiểm nghèo do di chứng chất độc da cam. Em phải đối mặt với sự phân biệt, với những cơn đau và chiếc xe lăn ngăn cách em với sân chơi của bè bạn cùng trang lứa.\n\nKhi đặt bút viết về Nhất Linh, mình không cần tưởng tượng xa xôi. Từng cảm giác bất lực khi đôi chân không chịu nghe lời, từng ánh mắt ái ngại của người lạ khi nhìn vào chiếc xe lăn – tất cả đều là những gì mình đã nếm trải suốt những năm tháng tuổi thơ ở Ba Vì.\n\nThế nhưng, điều làm nên sức sống của kịch bản không phải là căn bệnh, mà là **cách cô bé đối diện với nó**:\n- Nhất Linh không khóc lóc đòi hỏi sự thương hại.\n- Cô bé nuôi dưỡng một ước mơ cháy bỏng: trở thành một người có ích, giúp đỡ những bạn nhỏ có cùng hoàn cảnh và biến những điều tưởng chừng không thể thành hiện thực.\n\n## 3 nguyên tắc sống còn khi viết kịch bản thiếu nhi\n\nTừ trải nghiệm sáng tác *Ước mơ của em*, mình đúc rút được 3 bài học đắt giá cho các bạn biên kịch trẻ:\n\n### 1. Tuyệt đối không bi kịch hóa nhân vật yếu thế\nTrẻ em rất nhạy cảm. Nếu bạn nhồi nhét nước mắt và sự u uất, các em sẽ cảm thấy sợ hãi hoặc xa lánh. Hãy để nhân vật đối diện với nghịch cảnh bằng sự tò mò, lòng dũng cảm và trí tưởng tượng bay bổng. Chiếc xe lăn trong mắt trẻ thơ không phải là biểu tượng của sự tàn phế, nó có thể là một \"chiếc phi thuyền\" đưa em khám phá thế giới.\n\n### 2. Âm nhạc và nhịp điệu hành động phải đi cùng cảm xúc\nNhạc kịch đòi hỏi lời thoại phải cô đọng và có tính nhạc. Những phân đoạn nhân vật bộc lộ nội tâm phải được nâng đỡ bởi giai điệu, giúp các em nhỏ dễ nhớ, dễ hát và đồng cảm tự nhiên mà không cần rao giảng đạo đức.\n\n### 3. Gieo mầm niềm tin thay vì bài học giáo điều\nThông điệp lớn nhất mình gửi gắm qua vở kịch chính là:\n\n> *\"Dù các em là ai, khác biệt thế nào, cuộc sống có khắc nghiệt đến đâu, chỉ cần có ước mơ và lòng kiên định, các em sẽ luôn tìm được con đường dẫn tới hạnh phúc.\"*\n\nViết cho thiếu nhi chính là cơ hội để người lớn tự chữa lành cho đứa trẻ bên trong mình. Nhờ có Nhất Linh, cô bé Thanh Thanh năm 15 tuổi từng nằm khóc trong phòng bệnh đã thực sự mỉm cười và tìm thấy bình yên.',3,2,1,'published','2026-10-14 07:00:00','Kỹ thuật viết kịch bản thiếu nhi | Thanh Thanh','Bí quyết sáng tác kịch bản nhạc kịch thiếu nhi \"Ước mơ của em\" đạt giải nhất: Cách chuyển hóa nỗi đau cơ thể thành năng lượng hy vọng trong trẻo cho trẻ nhỏ.','vi','facebook',NULL,0,NULL,'2026-10-14 08:27:16','2026-10-14 08:27:16');
