REPLACE INTO `films` VALUES (1,'doi','ĐỢI','WAITING','An giam mình trong chiếc lồng tâm lý mang tên chờ đợi người khác, và trong chính lựa chọn của mình. Phải qua hết những điều ấy, cô mới tìm được lối ra.',NULL,'Phim ngắn · Chính kịch',8,'6 phút (bản dự thi)',2026,11,NULL,'- Biên kịch: Thanh Thanh\n- Vai chính (An): Thanh Thanh\n- Pitching trước: ĐD Trịnh Đình Lê Minh, chị Phạm Thị Hảo','Thanh Thanh','- Chung kết Inspiring Asia 2026, Manila, Philippines\n- Bán kết Inspiring Asia 2026: 1 trong 4 đại diện Việt Nam\n- Chung kết Inspiring Vietnam 2026, SIHUB, TP.HCM','Chung kết Inspiring Asia 2026 · Manila','phimngandoi','released',1,1,NULL,NULL,'2026-10-13 20:02:51','2026-10-13 22:21:13'),(2,'dua-con-den-tu-coi-am','Đứa con đến từ cõi âm',NULL,'Dự án phim điện ảnh đầu tay, lọt Top 7 From Script to Screen mùa 1.',NULL,'Phim điện ảnh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'- Top 7 From Script to Screen mùa 1','Top 7 From Script to Screen',NULL,'in_development',0,2,NULL,NULL,'2026-10-13 20:02:51','2026-10-13 20:02:51');
