REPLACE INTO `settings` VALUES (1,'site_name','Thanh Thanh','2026-10-13 20:02:51','2026-10-13 20:02:51'),(2,'site_tagline','Biên kịch','2026-10-13 20:02:51','2026-10-13 20:02:51'),(3,'mission','Đưa lát cắt đời sống người ngồi xe lăn vào điện ảnh.','2026-10-13 20:02:51','2026-10-13 20:02:51'),(4,'mission_intro','Mình là Thanh Thanh, biên kịch và vai chính của phim ngắn ĐỢI. Ở đây mình kể chuyện hậu trường, những “lần đầu tiên”, và những giới hạn mà không ai có quyền đặt ra cho mình.','2026-10-13 20:02:51','2026-10-13 20:02:51'),(5,'author_name','Thanh Thanh','2026-10-13 20:02:51','2026-10-13 20:02:51'),(6,'author_bio','Biên kịch ngồi xe lăn, tác giả phim ngắn ĐỢI (Chung kết Inspiring Asia 2026). Đang phát triển phim điện ảnh “Đứa con đến từ cõi âm”.','2026-10-13 20:02:51','2026-10-13 20:02:51'),(7,'social_facebook','https://www.facebook.com/thanhthanh.KOII','2026-10-13 20:02:51','2026-10-13 20:02:51'),(8,'social_threads','https://www.threads.net/@thanhthanh.koii','2026-10-13 20:02:51','2026-10-14 07:41:45'),(9,'contact_email','doicho147@gmail.com','2026-10-13 20:02:51','2026-10-14 07:41:45'),(10,'default_og_image','','2026-10-13 20:02:51','2026-10-13 20:02:51'),(11,'menu_main','[{\"label\":\"Hậu trường biên kịch\",\"url\":\"/hau-truong-bien-kich\"},{\"label\":\"Góc nghề\",\"url\":\"/goc-nghe\"},{\"label\":\"Phim\",\"url\":\"/phim\"},{\"label\":\"Giới thiệu\",\"url\":\"/gioi-thieu\"},{\"label\":\"EN · Press kit\",\"url\":\"/en/press-kit\",\"style\":\"button\"}]','2026-10-13 20:02:51','2026-10-13 20:02:51'),(12,'home_blocks','[\"hero-mission\",\"achievements\",\"featured-film\",\"script-preview\",\"latest-posts\",\"milestones\"]','2026-10-13 20:02:51','2026-10-14 07:47:59'),(13,'achievements','[{\"value\":\"Chung kết\",\"label\":\"Inspiring Asia 2026 · Manila\"},{\"value\":\"Chung kết\",\"label\":\"Inspiring Vietnam 2026 · SIHUB\"},{\"value\":\"Top 7\",\"label\":\"From Script to Screen mùa 1\"}]','2026-10-13 20:02:51','2026-10-13 20:02:51'),(24,'hero_media_id','8','2026-10-13 22:27:31','2026-10-13 22:27:31'),(26,'contact_address','Thôn Vân Sa, xã Cổ Đô, Hà Nội','2026-10-14 07:41:45','2026-10-14 07:41:45'),(29,'social_tiktok','https://www.tiktok.com/@thanhthanh.koii','2026-10-14 07:41:45','2026-10-14 07:41:45');
